-- The first firm's stages, fees, checklist items and template list, exactly as they were
-- when they were written into the app's code.
update public.firm_settings
   set stages = $json$[{"id":"stage1","label":"Stage 1: Preliminary Planning Investigations","shortLabel":"Stage 1","defaultFee":500,"description":"Pre-start meeting, desktop analysis, legislative assessment, development potential advice.","items":["Attend one (1) pre-start meeting with client and any other relevant consultants","Desktop analysis of site and surrounding uses","Assess proposed development against local and state government legislation","Identify zone, overlays and local plan requirements","Advise on the site's development potential and constraints","Identify and review relevant adjoining / nearby development approvals","Advise client of necessary external consultants for supporting information","Determine application type/s and council lodgement fees","Provide advice to client on development potential and progressing with a development application"]},{"id":"stage2","label":"Stage 2: Prepare and Lodge Development Application","shortLabel":"Stage 2","defaultFee":3000,"description":"Prepare design brief, engage consultants, prepare planning report, lodge with council.","items":["Prepare design brief for the architect/draftsman","Obtain quote/s, engage and co-ordinate external consultants (if required)","Review draft architectural plans and provide advice on any changes required","Review external consultant's reports and coordinate information","Prepare land owner's consent form for signing","Prepare Town Planning Report and Code Compliance Statements","Complete statutory application forms","Collate and lodge application with Council in compliance with the Planning Act 2016","Ensure application has been 'properly made' in accordance with the Planning Act 2016"]},{"id":"stage3","label":"Stage 3: Manage and Coordinate Post Lodgement Services","shortLabel":"Stage 3","defaultFee":2000,"description":"Project manage application through to decision notice.","items":["Project manage the development application with regards to the confirmation notice and information requests","Obtain quotes, engage and co-ordinate external consultants for amended or additional supporting information","Review and provide written responses to Council information request","Review and provide written responses to Council's further advice notice(s)","Ensure application is managed in accordance with the Planning Act 2016 and Development Assessment Rules","Attend one (1) meeting with consultants (if required) and one (1) meeting with council (if required)","Respond to Assessment Manager queries","Review and negotiate draft conditions","Provide client with digital copy of the Decision Notice","Advise client on approval conditions and/or appeal rights"]}]$json$::jsonb,
       templates = $json$[{"stage":"Stage 1","groups":[{"name":"Fee Proposals","items":[{"file":"Fee_Proposal_Code.docx","label":"Fee Proposal - Code Assessable"},{"file":"Fee_Proposal_Impact.docx","label":"Fee Proposal - Impact Assessable"},{"file":"Fee_Proposal_Minor_Change.docx","label":"Fee Proposal - Minor Change"},{"file":"Fee_Proposal_RAA.docx","label":"Fee Proposal - Referral Agency Assessment"}]},{"name":"Owner's Consent","items":[{"file":"Consent_Individual.docx","label":"Owner's Consent - Individual"},{"file":"Consent_Company.docx","label":"Owner's Consent - Company"}]}]},{"stage":"Stage 2","groups":[{"name":"Action Notice","items":[{"file":"Action_Notice_Response.docx","label":"Action Notice Response"}]},{"name":"Planning Reports","items":[{"file":"Town_Planning_Assessment.docx","label":"Town Planning Assessment (generic)"},{"file":"DA_Report_Brisbane.docx","label":"DA Report - Brisbane"},{"file":"DA_Report_Brisbane_RiskSmart.docx","label":"DA Report - Brisbane RiskSmart"},{"file":"DA_Report_Express_Code.docx","label":"DA Report - Express DA (Code)"},{"file":"DA_Report_Express_Accepted.docx","label":"DA Report - Express DA (Accepted to Code)"},{"file":"DA_Report_Gold_Coast.docx","label":"DA Report - Gold Coast"},{"file":"DA_Report_Gold_Coast_RAA.docx","label":"DA Report - Gold Coast RAA"},{"file":"DA_Report_Gold_Coast_Sch6_RAA.docx","label":"DA Report - Gold Coast Sch6 RAA"},{"file":"DA_Report_OPW.docx","label":"DA Report - Operational Works"}]},{"name":"Referrals","items":[{"file":"Referral_Cover_Letter.docx","label":"Referral Cover Letter"},{"file":"Missed_Referral_Letter.docx","label":"Missed Referral Letter"},{"file":"Referral_Compliance_Letter.docx","label":"Referral Compliance Letter"},{"file":"Early_Concurrence_Request.docx","label":"Early Concurrence Request"},{"file":"RAA_Application.docx","label":"RAA Application"}]},{"name":"Change Applications","items":[{"file":"Minor_Change_Application.docx","label":"Minor Change Application"},{"file":"Minor_Change_Application_Affected_Entity.docx","label":"Minor Change - Affected Entity Notice"},{"file":"Other_Change_Application.docx","label":"Other Change Application"}]}]},{"stage":"Stage 3","groups":[{"name":"Information Request","items":[{"file":"IR_Response.docx","label":"IR Response"},{"file":"Extend_Response_Period.docx","label":"Extend Response Period"},{"file":"Initial_Response_and_Direction.docx","label":"Initial Response & Direction"}]},{"name":"Public Notification","items":[{"file":"Notice_of_Commencement.docx","label":"Notice of Commencement"},{"file":"Notice_of_Compliance_to_Council.docx","label":"Notice of Compliance to Council"},{"file":"Notify_Adjoining_Owner_Letter.docx","label":"Notify Adjoining Owner Letter"},{"file":"Newspaper_Template.docx","label":"Newspaper Notice Template"}]},{"name":"Waive Appeal Rights","items":[{"file":"Waive_Appeal_Rights.docx","label":"Waive Appeal Rights"},{"file":"Waive_ICN_Appeal_Rights.docx","label":"Waive ICN Appeal Rights"},{"file":"Suspend_Applicant_Appeal_Period.docx","label":"Suspend Applicant Appeal Period"}]},{"name":"Tools & Forms","items":[{"file":"Adjoining_Owners_Contact_List.xlsx","label":"Adjoining Owners Contact List (Excel)"},{"file":"Advertising_Register.xlsx","label":"Advertising Register (Excel)"},{"file":"Calendar_2023.xlsx","label":"Calendar (Excel)"},{"file":"DA_Sign_Template.ai","label":"DA Sign Template (Illustrator)"},{"file":"Change_Application_Sign_Template.ai","label":"Change Application Sign Template (Illustrator)"}]}]},{"stage":"Miscellaneous","groups":[{"name":"Other","items":[{"file":"Lodgement_Cover_Letter.docx","label":"Lodgement Cover Letter"},{"file":"Withdraw_Application.docx","label":"Withdraw Application"},{"file":"Notice_to_Revive_Application.docx","label":"Notice to Revive Application"},{"file":"Notice_to_Stop_Current_Period.docx","label":"Notice to Stop Current Period"},{"file":"Quote_Request.docx","label":"Quote Request"}]},{"name":"Letterhead","items":[{"file":"Generic_Letterhead.docx","label":"Generic Letterhead (blank)"}]}]}]$json$::jsonb
